insert into public.concepts(id,course_id,slug,title,summary,order_index,content) values
('20000000-0000-4000-8000-000000001001','10000000-0000-4000-8000-000000000010','chemical-equations','Writing and balancing equations','Turning a chemical change into a balanced symbol equation that conserves atoms.',0,$c${"explanation":"A chemical reaction rearranges atoms: reactants are used up and products are formed, but no atom disappears. A word equation names them; a symbol equation uses formulae and state symbols such as (s), (l), (g) and (aq). Balancing means placing whole-number coefficients in front of formulae until every element has the same number of atoms on both sides, which expresses conservation of mass. Subscripts inside a formula must never be changed to balance an equation because that would change the substance itself. Check hydrogen and oxygen last, and simplify coefficients to the smallest whole-number ratio.","examples":[{"problem":"Balance: Fe + H₂O → Fe₃O₄ + H₂.","solution":"There are 3 Fe and 4 O on the right, so use 3Fe + 4H₂O → Fe₃O₄ + 4H₂. Hydrogen is then 8 on both sides."},{"problem":"Balance: Mg + O₂ → MgO.","solution":"Oxygen occurs as O₂, so use 2Mg + O₂ → 2MgO. Both sides now have 2 Mg and 2 O atoms."}],"misconceptions":["Changing a subscript in a formula balances the equation without changing the substance.","Mass is lost when a gas escapes, so the products may be lighter.","State symbols are decoration and never carry information."],"revision_notes":"Balance by adding coefficients only. Count every element on both sides, simplify the ratio, and include state symbols when they are known."}$c$::jsonb),
('20000000-0000-4000-8000-000000001002','10000000-0000-4000-8000-000000000010','types-of-reactions','Types of chemical reactions','Combination, decomposition, displacement, double displacement and precipitation reactions.',1,$c${"explanation":"Reactions are grouped by how atoms are rearranged. In a combination reaction two or more substances form one product, as when calcium oxide reacts with water to form calcium hydroxide. A decomposition reaction splits one compound into simpler substances using heat, electricity or light. In a displacement reaction a more reactive element replaces a less reactive one in a compound. In a double displacement reaction ions exchange partners, often forming a precipitate or water. Neutralisation is a double displacement producing a salt and water. Recognising the pattern helps predict products and write the equation.","examples":[{"problem":"Classify: Fe + CuSO₄ → FeSO₄ + Cu.","solution":"Iron displaces copper because iron is more reactive, so this is a displacement reaction."},{"problem":"Classify: AgNO₃(aq) + NaCl(aq) → AgCl(s) + NaNO₃(aq).","solution":"Ions exchange partners and a white precipitate of silver chloride forms, so it is a double displacement (precipitation) reaction."}],"misconceptions":["Every reaction that produces a gas is a decomposition reaction.","A precipitate is a gas escaping from the solution.","A less reactive metal can displace a more reactive metal from its salt."],"revision_notes":"Combination: many → one. Decomposition: one → many (heat, light or electricity). Displacement: reactive element replaces a less reactive one. Double displacement: ions swap; watch for a precipitate."}$c$::jsonb),
('20000000-0000-4000-8000-000000001003','10000000-0000-4000-8000-000000000010','redox-reactions','Oxidation, reduction and redox','Electron and oxygen transfer, oxidising and reducing agents, corrosion and rancidity.',2,$c${"explanation":"Oxidation is the loss of electrons or the gain of oxygen; reduction is the gain of electrons or the loss of oxygen. The two always occur together in a redox reaction, and the substance oxidised is the reducing agent while the substance reduced is the oxidising agent. For example, in CuO + H₂ → Cu + H₂O, copper(II) oxide loses oxygen and is reduced, while hydrogen gains oxygen and is oxidised. Redox explains corrosion: iron reacts with oxygen and water to form hydrated iron(III) oxide, rust. Fats and oils in food are oxidised by air, causing rancidity, which antioxidants and airtight packaging slow down.","examples":[{"problem":"In Fe₂O₃ + 3CO → 2Fe + 3CO₂, identify what is oxidised and reduced.","solution":"Fe₂O₃ loses oxygen, so it is reduced. CO gains oxygen and is oxidised to CO₂; CO is the reducing agent."},{"problem":"Why do packets of chips contain nitrogen?","solution":"Nitrogen replaces oxygen, slowing oxidation of the fats and oils that makes the food rancid."}],"misconceptions":["Oxidation always involves oxygen gas.","Reduction means the substance loses mass.","An oxidising agent is itself oxidised."],"revision_notes":"OIL RIG: oxidation is loss, reduction is gain (of electrons). Oxidising agent is reduced; reducing agent is oxidised. Rust = iron + oxygen + water; rancidity = oxidation of fats/oils."}$c$::jsonb),
('20000000-0000-4000-8000-000000001004','10000000-0000-4000-8000-000000000010','reaction-energy','Energy changes and reaction conditions','Exothermic and endothermic changes, catalysts, and how conditions affect reactions.',3,$c${"explanation":"Every reaction either releases energy to the surroundings or absorbs energy from them. An exothermic reaction, such as combustion or respiration, warms the surroundings because the products have less stored chemical energy than the reactants. An endothermic reaction, such as photosynthesis or the thermal decomposition of calcium carbonate, cools the surroundings and needs a continuing energy supply. Many reactions need an initial energy input to start, and a catalyst lowers the barrier without being used up. Temperature, concentration, surface area and catalysts change how quickly a reaction proceeds, while some reactions also require heat, light or electricity to occur at all.","examples":[{"problem":"Is the burning of magnesium exothermic or endothermic?","solution":"Exothermic: it releases heat and light, and the surroundings become warmer."},{"problem":"Why does powdered calcium carbonate react faster with acid than a single lump?","solution":"The powder exposes a much larger surface area, so acid particles collide with the solid more often."}],"misconceptions":["Endothermic reactions do not need energy.","A catalyst is consumed during the reaction.","A reaction stops as soon as all the reactants are used up — actually it stops when a reactant runs out, not when the catalyst does."],"revision_notes":"Exothermic releases heat; endothermic absorbs heat. Catalysts speed reactions without being used up. Rate rises with temperature, concentration and surface area."}$c$::jsonb),
('20000000-0000-4000-8000-000000001005','10000000-0000-4000-8000-000000000011','euclid-division','Euclid''s division lemma and HCF','Using a = bq + r repeatedly to find the highest common factor.',0,$c${"explanation":"Euclid's division lemma says that for positive integers a and b there are unique whole numbers q and r with a = bq + r and 0 ≤ r < b. To find the HCF of two numbers, divide the larger by the smaller, then replace the pair by the divisor and remainder and repeat until the remainder is zero. The last non-zero divisor is the HCF. The method works because any common divisor of a and b also divides r, so the common divisors do not change during the process. It is efficient even for large numbers and does not require factorising them first.","examples":[{"problem":"Find the HCF of 455 and 42 using Euclid's algorithm.","solution":"455 = 42 × 10 + 35; 42 = 35 × 1 + 7; 35 = 7 × 5 + 0. The last non-zero divisor is 7, so HCF = 7."},{"problem":"Find the HCF of 867 and 255.","solution":"867 = 255 × 3 + 102; 255 = 102 × 2 + 51; 102 = 51 × 2 + 0. HCF = 51."}],"misconceptions":["The remainder may be larger than the divisor.","The HCF is the last remainder rather than the last non-zero divisor.","Euclid's algorithm only works for even numbers."],"revision_notes":"a = bq + r, 0 ≤ r < b. Replace (a, b) by (b, r) until r = 0. The last non-zero divisor is the HCF."}$c$::jsonb),
('20000000-0000-4000-8000-000000001006','10000000-0000-4000-8000-000000000011','fundamental-theorem','Prime factorisation and irrational numbers','Unique prime factorisation, HCF and LCM, and proving that √2 is irrational.',1,$c${"explanation":"The fundamental theorem of arithmetic states that every integer greater than 1 has a unique prime factorisation apart from the order of the factors. From the factorisations, the HCF is the product of the smallest powers of common primes, while the LCM is the product of the largest powers of all primes present. For two positive integers, HCF × LCM equals their product. Prime factorisation also proves irrationality: if √2 were rational, it could be written in lowest terms as p/q; squaring gives p² = 2q², so p is even, and then q is also even, contradicting lowest terms.","examples":[{"problem":"Find the HCF and LCM of 12 and 18.","solution":"12 = 2² × 3 and 18 = 2 × 3². HCF = 2 × 3 = 6; LCM = 2² × 3² = 36. Check: 6 × 36 = 216 = 12 × 18."},{"problem":"Explain why √5 cannot be written as a fraction in lowest terms.","solution":"If √5 = p/q in lowest terms, then p² = 5q², so 5 divides p² and hence p. Writing p = 5k gives 5k² = q², so 5 divides q too, contradicting that p and q have no common factor."}],"misconceptions":["Different prime factorisations of the same number are possible.","HCF is always the product of all the primes in both numbers.","Every square root is irrational."],"revision_notes":"Unique prime factorisation. HCF uses lowest powers of common primes; LCM uses highest powers. HCF × LCM = product for two numbers. Irrationality is proved by contradiction."}$c$::jsonb),
('20000000-0000-4000-8000-000000001007','10000000-0000-4000-8000-000000000011','polynomial-zeros','Polynomials and their zeros','Degree, zeros, graphs and the relationship between zeros and coefficients.',2,$c${"explanation":"A polynomial in x is a sum of terms aₙxⁿ with non-negative whole-number powers; its degree is the highest power with a non-zero coefficient. A zero of a polynomial p(x) is a value c for which p(c) = 0, and on the graph these are the points where the curve meets the x-axis. A linear polynomial has one zero, a quadratic has at most two and a cubic at most three. For a quadratic ax² + bx + c, the zeros α and β satisfy α + β = -b/a and αβ = c/a. These relationships let you reconstruct a quadratic from its zeros or check a factorisation.","examples":[{"problem":"Find the zeros of x² - 5x + 6.","solution":"Factorise: (x - 2)(x - 3) = 0, so the zeros are 2 and 3. Check: sum = 5 = -(-5)/1 and product = 6 = 6/1."},{"problem":"Form a quadratic whose zeros are -2 and 4.","solution":"Sum = 2, product = -8. Use x² - (sum)x + product = x² - 2x - 8."}],"misconceptions":["The degree is the number of terms.","Every quadratic has two distinct real zeros.","The graph's y-intercept is a zero of the polynomial."],"revision_notes":"Zero: p(c) = 0, where the graph cuts the x-axis. Quadratic: α + β = -b/a, αβ = c/a. Form a quadratic from x² - (sum)x + product."}$c$::jsonb),
('20000000-0000-4000-8000-000000001008','10000000-0000-4000-8000-000000000011','polynomial-division','Division algorithm, remainder and factor theorems','Dividing polynomials and using remainders to test factors.',3,$c${"explanation":"For polynomials p(x) and a non-zero divisor g(x), the division algorithm gives p(x) = g(x)q(x) + r(x), where either r(x) is zero or its degree is less than the degree of g(x). If g(x) = x - a, the remainder is simply p(a). This is the remainder theorem. Consequently, x - a is a factor of p(x) exactly when p(a) = 0, which is the factor theorem. These results let you test possible factors quickly, divide out known factors and factorise cubics by combining the factor theorem with long division or splitting the middle term.","examples":[{"problem":"Find the remainder when p(x) = x³ - 2x² + 4x - 3 is divided by x - 2.","solution":"By the remainder theorem, the remainder is p(2) = 8 - 8 + 8 - 3 = 5."},{"problem":"Show that x - 1 is a factor of x³ - 3x² + 4x - 2.","solution":"p(1) = 1 - 3 + 4 - 2 = 0, so by the factor theorem x - 1 is a factor."}],"misconceptions":["The remainder theorem gives the quotient.","x - a is a factor whenever p(a) is non-zero.","The remainder can have the same degree as the divisor."],"revision_notes":"p(x) = g(x)q(x) + r(x), deg r < deg g. For g = x - a, remainder = p(a). x - a is a factor exactly when p(a) = 0."}$c$::jsonb),
('20000000-0000-4000-8000-000000001009','10000000-0000-4000-8000-000000000012','nutrition','Nutrition and digestion','Autotrophic and heterotrophic nutrition, photosynthesis, and the human digestive system.',0,$c${"explanation":"Nutrition supplies the matter and energy organisms need. Autotrophs such as green plants make food by photosynthesis: carbon dioxide and water, using light energy absorbed by chlorophyll, form glucose and release oxygen. Heterotrophs depend on other organisms; humans digest food extracellularly before absorbing it. In the mouth, salivary amylase begins starch digestion; in the stomach, hydrochloric acid provides an acidic medium and pepsin digests proteins; in the small intestine, bile emulsifies fats and pancreatic and intestinal enzymes complete the breakdown. Villi increase the surface area for absorption into the blood.","examples":[{"problem":"Write the word equation for photosynthesis.","solution":"Carbon dioxide + water → glucose + oxygen, in the presence of chlorophyll and light energy."},{"problem":"Why is bile important for fat digestion?","solution":"Bile salts emulsify large fat droplets into smaller ones, increasing the surface area on which lipase can act."}],"misconceptions":["Plants get their food from the soil.","Digestion of starch begins in the stomach.","Villi increase the length of the intestine rather than its absorptive surface area."],"revision_notes":"Photosynthesis: CO₂ + H₂O + light → glucose + O₂. Amylase: starch; pepsin: protein in acid; bile emulsifies fat; lipase: fat. Villi absorb nutrients."}$c$::jsonb),
('20000000-0000-4000-8000-000000001010','10000000-0000-4000-8000-000000000012','respiration','Respiration and gas exchange','Aerobic and anaerobic respiration, ATP, and how the human respiratory system works.',1,$c${"explanation":"Respiration releases energy from food in cells. Aerobic respiration uses oxygen and breaks glucose down completely to carbon dioxide and water, releasing a large amount of energy as ATP. Anaerobic respiration occurs without oxygen and releases less energy; in human muscle it produces lactic acid, and in yeast it produces ethanol and carbon dioxide. Breathing supplies oxygen and removes carbon dioxide. Air enters through the nose, trachea, bronchi and bronchioles and reaches alveoli, where thin moist walls and a rich blood supply allow rapid diffusion. Haemoglobin in red blood cells carries oxygen around the body.","examples":[{"problem":"Compare the energy released by aerobic and anaerobic respiration of one glucose molecule.","solution":"Aerobic respiration releases far more energy because glucose is fully oxidised to CO₂ and water; anaerobic products still contain stored chemical energy."},{"problem":"Why do alveoli have thin walls and many capillaries?","solution":"This gives a short diffusion distance and maintains a steep concentration gradient for oxygen and carbon dioxide."}],"misconceptions":["Respiration and breathing are the same process.","Anaerobic respiration produces carbon dioxide in human muscles.","Plants do not respire during the day."],"revision_notes":"Aerobic: glucose + O₂ → CO₂ + H₂O + much ATP. Anaerobic muscle: glucose → lactic acid + less ATP; yeast: ethanol + CO₂. Alveoli: thin, moist, large area, rich blood supply."}$c$::jsonb),
('20000000-0000-4000-8000-000000001011','10000000-0000-4000-8000-000000000012','transportation','Transport in humans and plants','Blood, the heart, double circulation, and xylem and phloem transport.',2,$c${"explanation":"Complex organisms need a transport system because diffusion alone cannot supply all their cells. Human blood carries oxygen, nutrients, hormones, carbon dioxide and urea; plasma is the liquid medium, red cells carry oxygen, white cells defend the body and platelets help clotting. The heart pumps blood through two circuits: pulmonary to the lungs and systemic to the body, a double circulation that keeps oxygenated and deoxygenated blood separate and maintains pressure. Arteries carry blood away from the heart under high pressure, veins return it through valves, and capillaries exchange materials. Plants use xylem for water and minerals and phloem for sugars.","examples":[{"problem":"Why is double circulation important for a mammal?","solution":"It separates oxygenated and deoxygenated blood and allows the systemic circuit to deliver blood at high pressure without damaging the lungs."},{"problem":"How does water rise in a tall tree?","solution":"Transpiration at the leaves pulls water upward through xylem; cohesion between water molecules and adhesion to xylem walls keep the column continuous."}],"misconceptions":["Arteries always carry oxygenated blood.","Veins pump blood back to the heart.","Phloem transports water upward from the roots."],"revision_notes":"Double circulation: pulmonary + systemic. Arteries away, veins toward, capillaries exchange. Xylem: water/minerals up; phloem: sugars both ways. Transpiration pull."}$c$::jsonb),
('20000000-0000-4000-8000-000000001012','10000000-0000-4000-8000-000000000012','excretion','Excretion and osmoregulation','The nephron, urine formation, dialysis and waste removal in plants.',3,$c${"explanation":"Excretion removes metabolic wastes. The kidneys filter blood and regulate water and salt balance. Blood enters a nephron through a glomerulus, where pressure forces water, glucose, salts and urea into Bowman's capsule. As the filtrate passes along the tubule, useful glucose, some salts and most water are reabsorbed; excess ions and drugs are secreted, and the remaining urine passes to the bladder. Dialysis performs the same filtering job artificially using a selectively permeable membrane and a fluid with the correct solute concentrations. Plants remove excess water by transpiration and store or shed other wastes in leaves, resins and bark.","examples":[{"problem":"Why is glucose absent from normal urine?","solution":"Glucose is completely reabsorbed from the proximal tubule into the blood, so it does not normally remain in the filtrate."},{"problem":"Why does dialysis fluid contain no urea?","solution":"A steep concentration gradient lets urea diffuse out of the blood into the fluid, while useful solutes remain at balanced concentrations."}],"misconceptions":["Urine is formed by filtration only.","The kidneys remove undigested food.","Dialysing fluid should contain urea to clean the blood."],"revision_notes":"Nephron: filtration at glomerulus, selective reabsorption, secretion. Glucose and most water return to blood. Dialysis uses diffusion down gradients. Plants excrete via transpiration and storage."}$c$::jsonb),
('20000000-0000-4000-8000-000000001013','10000000-0000-4000-8000-000000000013','comprehension','Comprehension and inference','Reading for explicit meaning, inference, theme and evidence.',0,$c${"explanation":"Strong comprehension separates what a text says from what it suggests. First read for the gist, then locate key details by scanning for names, dates and repeated ideas. Inference means drawing a conclusion that the text supports but does not state directly, for example recognising a character's fear from their hesitation. Theme is the central idea developed across the whole passage, not a single fact. Every answer should be supported by a short quotation or a precise reference. When asked for the meaning of a word in context, replace it with a synonym and check that the sentence still makes sense.","examples":[{"problem":"A passage says a boy 'clutched the railing until his knuckles whitened' before a speech. What can you infer?","solution":"He is extremely nervous. The physical detail of his grip and pale knuckles implies tension even though nervousness is not stated."},{"problem":"How do you answer a 'theme' question in one sentence?","solution":"Name the idea and add the evidence: 'The passage explores the cost of ambition, shown when the narrator sacrifices sleep to finish the project.'"}],"misconceptions":["Any personal opinion counts as an inference.","A theme is the same as the plot.","A quotation can be used without explaining how it supports the answer."],"revision_notes":"Skim for gist, scan for detail. Inference = supported conclusion. Theme = central idea + evidence. Quote briefly and explain the link."}$c$::jsonb),
('20000000-0000-4000-8000-000000001014','10000000-0000-4000-8000-000000000013','poetry-analysis','Poetry and figurative language','Speaker, imagery, sound devices, tone and theme in poems.',1,$c${"explanation":"In poetry, meaning is carried by both what is said and how it is shaped on the page and in the ear. Identify the speaker separately from the poet; the voice may be a persona. Look at imagery and figurative language: a simile compares using like or as, a metaphor states one thing is another, and personification gives human qualities to non-human things. Sound devices such as alliteration, rhyme and rhythm create mood and emphasis. Tone is the speaker's attitude, while theme is the larger idea. Link every device to its effect rather than merely naming it.","examples":[{"problem":"What is the effect of 'the wind whispered through the leaves'?","solution":"Personification makes the wind sound secretive and gentle, creating a calm, slightly mysterious mood."},{"problem":"How should you write about a metaphor?","solution":"Name it, quote it and explain its effect: 'The metaphor of the classroom as a battlefield presents learning as a struggle the students must win.'"}],"misconceptions":["The speaker is always the poet.","Naming a device is the same as analysing it.","A poem has one fixed meaning that ignores tone."],"revision_notes":"Separate speaker and poet. Device → quotation → effect. Simile (like/as), metaphor (is), personification. Tone = attitude; theme = central idea."}$c$::jsonb),
('20000000-0000-4000-8000-000000001015','10000000-0000-4000-8000-000000000013','grammar-editing','Grammar and editing','Tense, agreement, determiners, reported speech and error correction.',2,$c${"explanation":"Accurate writing depends on a few high-value grammar choices. Keep tenses consistent unless the time sequence genuinely changes. A verb must agree with its subject, even when a phrase sits between them: 'The box of books is heavy.' Determiners such as a, an, the, some and every must fit the noun. In reported speech, shift the tense back and adjust pronouns and time words: 'I am tired' becomes 'She said that she was tired.' Editing tasks test small slips such as missing articles, wrong prepositions, subject-verb disagreement and unnecessary words. Read the whole sentence before changing anything.","examples":[{"problem":"Correct: 'Each of the students have submitted their work.'","solution":"Each is singular, so use 'Each of the students has submitted their work.'"},{"problem":"Report: 'We will meet tomorrow,' said Ravi.","solution":"Ravi said that they would meet the next day."}],"misconceptions":["A verb agrees with the nearest noun rather than the subject.","Reported speech keeps every tense and time word unchanged.","An edit must change the meaning of the sentence."],"revision_notes":"Consistent tense; subject-verb agreement; suitable determiners; backshift in reported speech. Edit the smallest unit that fixes the error."}$c$::jsonb),
('20000000-0000-4000-8000-000000001016','10000000-0000-4000-8000-000000000013','writing-skills','Formal writing and analytical paragraphs','Letters, notices, analytical paragraphs and emails with purpose and structure.',3,$c${"explanation":"Every writing task has a purpose, audience and format. A formal letter uses the sender's address, date, receiver's address, subject, salutation, a clear opening, organised body paragraphs and a formal closing. A notice is short and factual, with a heading, date and contact details. An analytical paragraph states a claim, gives evidence from the text or data, explains the evidence and links back to the claim. An email uses a clear subject line and a polite, concise body. Choose linkers such as 'however', 'therefore' and 'for example' to show relationships, and reserve time to check spelling, agreement and punctuation.","examples":[{"problem":"Write the opening of a formal letter complaining about a broken library light.","solution":"'I am writing to report that the reading-room light has been out of order for a week. This has made evening study difficult for students.' State the problem and its effect immediately."},{"problem":"Build a three-sentence analytical paragraph about a character's courage.","solution":"Claim: 'Meena shows courage.' Evidence: 'She enters the flooded street to rescue the child.' Explanation: 'Her action despite fear reveals courage as doing what is right, not feeling no fear.'"}],"misconceptions":["A formal letter can use contractions and slang.","An analytical paragraph only needs a summary of events.","A notice should tell a long story to attract readers."],"revision_notes":"Identify purpose/audience/format. Formal letter: addresses, date, subject, salutation, body, closing. Analytical paragraph: claim, evidence, explanation, link. Check accuracy at the end."}$c$::jsonb),
('20000000-0000-4000-8000-000000001017','10000000-0000-4000-8000-000000000014','mole-concept','Atomic mass, molar mass and the mole','Counting particles by weighing, using Avogadro''s number and molar mass.',0,$c${"explanation":"Atoms are too small to count individually, so chemists count them in moles. One mole contains 6.022 × 10²³ particles, Avogadro's number. The molar mass of a substance is its mass in grams per mole and is numerically equal to its relative atomic or molecular mass. For example, water has a molar mass of about 18 g/mol, so 18 g of water contains one mole of water molecules. The relationships n = m/M, N = nN_A and, for a gas at standard conditions, V = n × 22.4 L connect amount, mass, particle number and volume. Always state the unit and the particle being counted.","examples":[{"problem":"How many moles are in 11 g of carbon dioxide (M = 44 g/mol)?","solution":"n = m/M = 11/44 = 0.25 mol, which contains 0.25 × 6.022 × 10²³ = 1.51 × 10²³ molecules."},{"problem":"What is the mass of 0.5 mol of sodium chloride (M = 58.5 g/mol)?","solution":"m = nM = 0.5 × 58.5 = 29.25 g."}],"misconceptions":["One mole of every substance has the same mass.","Molar mass is measured in grams.","Avogadro's number counts grams rather than particles."],"revision_notes":"1 mol = 6.022 × 10²³ particles. n = m/M; N = nN_A. Molar mass in g/mol is numerically the relative molecular mass."}$c$::jsonb),
('20000000-0000-4000-8000-000000001018','10000000-0000-4000-8000-000000000014','stoichiometry','Stoichiometry and limiting reagents','Using balanced equations to calculate masses, moles and yields.',1,$c${"explanation":"A balanced equation gives the mole ratio in which substances react and are produced. Stoichiometry converts the amount of a known substance into moles, applies that ratio and converts back to the requested quantity. When reactants are not present in the exact ratio, the limiting reagent is used up first and determines the maximum product; the other reactant is in excess. The theoretical yield comes from the limiting reagent, while the actual yield is what is obtained in practice. Percentage yield = actual/theoretical × 100, and it cannot exceed 100% in a correctly performed calculation.","examples":[{"problem":"How many grams of water form when 4 g of hydrogen reacts completely with oxygen? (H₂ + ½O₂ → H₂O; M(H₂) = 2, M(H₂O) = 18)","solution":"4 g H₂ = 2 mol. The ratio is 1:1, so 2 mol water forms: 2 × 18 = 36 g."},{"problem":"2 mol H₂ and 1 mol O₂ react. Which is limiting?","solution":"The equation needs 2 mol H₂ per 1 mol O₂, so they are in the exact ratio and neither is limiting; both are consumed."}],"misconceptions":["The reactant with the greater mass is always in excess.","Percentage yield can legitimately be 120%.","Mole ratios come from the masses rather than the balanced equation."],"revision_notes":"Convert to moles → use coefficients → convert back. Limiting reagent runs out first and sets theoretical yield. % yield = actual/theoretical × 100."}$c$::jsonb),
('20000000-0000-4000-8000-000000001019','10000000-0000-4000-8000-000000000014','concentration-units','Concentration of solutions','Molarity, molality, mole fraction, mass percentage and dilution.',2,$c${"explanation":"Concentration expresses how much solute is present in a given amount of solution or solvent. Molarity (M) is moles of solute per litre of solution and changes with temperature because volume changes. Molality (m) is moles of solute per kilogram of solvent and is temperature-independent. Mass percentage uses mass of solute per 100 g of solution, mole fraction compares moles of one component with total moles, and ppm is used for very dilute solutions. When a solution is diluted, the amount of solute is unchanged, so M₁V₁ = M₂V₂. Always distinguish solution volume from solvent mass.","examples":[{"problem":"0.5 mol of NaCl is dissolved to make 250 mL of solution. Find the molarity.","solution":"V = 0.250 L, so M = n/V = 0.5/0.250 = 2.0 mol/L."},{"problem":"100 mL of 2 M HCl is diluted to 500 mL. Find the new concentration.","solution":"M₁V₁ = M₂V₂, so 2 × 100 = M₂ × 500 and M₂ = 0.4 M."}],"misconceptions":["Molarity uses kilograms of solvent.","Dilution changes the number of moles of solute.","Mole fraction is measured in moles per litre."],"revision_notes":"M = mol/L solution; m = mol/kg solvent. Mass % = solute mass/solution mass × 100. Dilution: M₁V₁ = M₂V₂ (moles constant)."}$c$::jsonb),
('20000000-0000-4000-8000-000000001020','10000000-0000-4000-8000-000000000014','empirical-molecular','Empirical and molecular formulae','Finding formulae from percentage composition and molar mass.',3,$c${"explanation":"The empirical formula gives the simplest whole-number ratio of atoms in a compound; the molecular formula gives the actual number of atoms in one molecule and is a whole-number multiple of the empirical formula. From percentage composition, assume a 100 g sample, convert each mass to moles, divide by the smallest number of moles and convert the result to whole numbers. If the ratio is not close to whole numbers, multiply all values by a small integer. Then divide the molar mass by the empirical formula mass to find the multiplier. Combustion analysis uses the masses of CO₂ and H₂O produced to find carbon and hydrogen content.","examples":[{"problem":"A compound is 40% C, 6.7% H and 53.3% O by mass with molar mass 180 g/mol. Find its molecular formula.","solution":"In 100 g: C 3.33 mol, H 6.7 mol, O 3.33 mol. Ratio 1:2:1, so empirical formula CH₂O (mass 30). 180/30 = 6, so molecular formula C₆H₁₂O₆."},{"problem":"Why can the empirical formula of ethene be CH₂ while its molecular formula is C₂H₄?","solution":"Both have the same ratio, but the molecular formula reflects the two carbon atoms actually present in each molecule."}],"misconceptions":["The empirical formula is always the molecular formula.","Percentage composition gives masses that can be used directly as mole ratios.","A ratio of 1:1.5 should be left as decimals."],"revision_notes":"Assume 100 g → moles → divide by smallest → whole-number ratio. Molecular formula = empirical × (molar mass/empirical mass)."}$c$::jsonb),
('20000000-0000-4000-8000-000000001021','10000000-0000-4000-8000-000000000015','sets','Sets and set operations','Notation, subsets, unions, intersections, complements and Venn diagrams.',0,$c${"explanation":"A set is a well-defined collection of distinct objects. Sets can be written in roster form or set-builder notation. The empty set has no elements; A is a subset of B if every element of A belongs to B, and the power set of A is the set of all its subsets. The union A ∪ B contains elements in either set, the intersection A ∩ B contains elements in both, and the complement A' contains elements of the universal set not in A. The difference A - B contains elements of A not in B. Venn diagrams make these relationships visible, and De Morgan's laws connect complements with unions and intersections.","examples":[{"problem":"A = {1, 2, 3, 4} and B = {3, 4, 5}. Find A ∪ B, A ∩ B and A - B.","solution":"A ∪ B = {1, 2, 3, 4, 5}; A ∩ B = {3, 4}; A - B = {1, 2}."},{"problem":"How many subsets does a set with 3 elements have?","solution":"2³ = 8 subsets, including the empty set and the set itself."}],"misconceptions":["A set may contain the same element twice.","The empty set is a subset of no set.","A - B is the same as B - A."],"revision_notes":"Roster or set-builder. Subsets: 2ⁿ. Union ∪, intersection ∩, complement ', difference A - B. De Morgan: (A ∪ B)' = A' ∩ B'."}$c$::jsonb),
('20000000-0000-4000-8000-000000001022','10000000-0000-4000-8000-000000000015','relations','Cartesian products and relations','Ordered pairs, domains, ranges and types of relations.',1,$c${"explanation":"The Cartesian product A × B is the set of all ordered pairs (a, b) with a in A and b in B. A relation from A to B is any subset of A × B. The domain is the set of first coordinates that appear, and the range is the set of second coordinates. Relations can be reflexive, symmetric or transitive. A relation on a set is reflexive if every element is related to itself, symmetric if aRb implies bRa, and transitive if aRb and bRc imply aRc. A relation with all three properties is an equivalence relation, which partitions the set into classes.","examples":[{"problem":"A = {1, 2}, B = {x, y}. List A × B.","solution":"A × B = {(1, x), (1, y), (2, x), (2, y)}."},{"problem":"Is 'has the same birthday as' an equivalence relation?","solution":"Yes: reflexive, symmetric and transitive. It partitions people into groups sharing a birthday."}],"misconceptions":["A relation must relate every element of A to every element of B.","The range is the same as the codomain.","Symmetry and transitivity together guarantee reflexivity."],"revision_notes":"A × B = all ordered pairs. Relation ⊆ A × B. Domain = first coordinates, range = second. Equivalence = reflexive + symmetric + transitive."}$c$::jsonb),
('20000000-0000-4000-8000-000000001023','10000000-0000-4000-8000-000000000015','functions','Functions and their properties','Domain, codomain, range, one-one and onto functions, composition and inverses.',2,$c${"explanation":"A function f: A → B assigns exactly one element of B to each element of A. The domain is A, the codomain is B and the range is the set of values actually attained. A function is one-one (injective) if different inputs always give different outputs, and onto (surjective) if every element of the codomain is attained. A function that is both is bijective and has an inverse function. Composition (f ∘ g)(x) = f(g(x)) is defined only when the range of g lies within the domain of f. The inverse undoes the function, so f⁻¹(f(x)) = x and the graphs are reflections in y = x.","examples":[{"problem":"For f(x) = 2x + 3 on the reals, find f⁻¹(x).","solution":"Let y = 2x + 3, so x = (y - 3)/2. Therefore f⁻¹(x) = (x - 3)/2, defined for all real x."},{"problem":"Is f(x) = x² from ℝ to ℝ onto?","solution":"No: its range is [0, ∞), so negative real numbers are never attained."}],"misconceptions":["Every function has an inverse.","The codomain is always equal to the range.","f(g(x)) always equals g(f(x))."],"revision_notes":"Function: one output per input. One-one: f(a) = f(b) ⇒ a = b. Onto: range = codomain. Bijective ⇒ inverse exists. f⁻¹ undoes f."}$c$::jsonb),
('20000000-0000-4000-8000-000000001024','10000000-0000-4000-8000-000000000015','function-graphs','Graphs and transformations','Reading domains and ranges from graphs and applying shifts, stretches and reflections.',3,$c${"explanation":"A graph shows a function's behaviour: its domain is the set of x-values covered, and its range is the set of y-values reached. Transformations follow reliable rules. Replacing x by x - h shifts the graph h units right; adding k outside shifts it k units up. Multiplying the output by a stretches or compresses it vertically, while multiplying the input by b stretches or compresses it horizontally. A negative outside the function reflects it in the x-axis, and a negative on the input reflects it in the y-axis. Even functions satisfy f(-x) = f(x) and are symmetric about the y-axis; odd functions satisfy f(-x) = -f(x).","examples":[{"problem":"Describe the graph of y = (x - 2)² + 3 compared with y = x².","solution":"Shift y = x² two units right and three units up; the vertex moves from (0, 0) to (2, 3)."},{"problem":"Is f(x) = x³ even, odd or neither?","solution":"f(-x) = -x³ = -f(x), so it is odd and has rotational symmetry about the origin."}],"misconceptions":["Adding a constant inside the bracket shifts the graph up.","A negative sign always reflects in the x-axis.","An even function must be positive everywhere."],"revision_notes":"Inside change → horizontal (opposite sign); outside change → vertical. Even: y-axis symmetry; odd: origin symmetry. Domain from x-span, range from y-span."}$c$::jsonb),
('20000000-0000-4000-8000-000000001025','10000000-0000-4000-8000-000000000016','cell-theory','Cell theory and cell types','Prokaryotic and eukaryotic cells, microscopy and the cell theory.',0,$c${"explanation":"Cell theory states that all living organisms are made of cells, that the cell is the basic unit of life, and that new cells arise from existing cells. Prokaryotic cells, such as bacteria, lack a membrane-bound nucleus and organelles; their DNA lies in a nucleoid, and they have ribosomes, a plasma membrane and usually a cell wall. Eukaryotic cells have a true nucleus enclosed by a nuclear envelope and membrane-bound organelles. Plant cells have a cellulose cell wall, chloroplasts and a large central vacuole, while animal cells have centrioles and no cell wall. Microscopy and cell fractionation made these structures visible and separable.","examples":[{"problem":"Give two structural differences between plant and animal cells.","solution":"Plant cells have a cellulose cell wall and chloroplasts; animal cells have neither but do have centrioles."},{"problem":"Why can a bacterium carry out life processes without a nucleus?","solution":"Its DNA is in the nucleoid and its ribosomes make proteins; membrane-bound compartmentalisation is not required for its basic metabolism."}],"misconceptions":["All cells have a nucleus.","Prokaryotes have no DNA.","Plant cells do not have mitochondria."],"revision_notes":"Cell theory: all organisms are cellular, cell = basic unit, cells come from cells. Prokaryote: no nucleus/organelles. Plant: wall, chloroplast, large vacuole."}$c$::jsonb),
('20000000-0000-4000-8000-000000001026','10000000-0000-4000-8000-000000000016','cell-organelles','Membrane structure and organelles','The fluid mosaic membrane and the roles of the major organelles.',1,$c${"explanation":"The plasma membrane is a fluid mosaic of phospholipids, proteins and cholesterol. Its hydrophobic core blocks many polar substances, so transport uses channels, carriers, pumps, osmosis and vesicle traffic. The nucleus stores DNA and controls protein synthesis through mRNA. Ribosomes assemble proteins; the rough endoplasmic reticulum folds and transports them, while the smooth ER makes lipids. The Golgi apparatus modifies, sorts and packages molecules. Mitochondria carry out aerobic respiration, chloroplasts perform photosynthesis in plants, lysosomes contain digestive enzymes, and vacuoles store materials and maintain turgor. Each organelle's structure supports its function.","examples":[{"problem":"Why are mitochondria called the powerhouse of the cell?","solution":"They oxidise pyruvate and fatty acids through the Krebs cycle and oxidative phosphorylation, producing most of the cell's ATP."},{"problem":"What happens to a protein destined for secretion after it is made on the rough ER?","solution":"It is folded in the ER, transported in vesicles to the Golgi for modification and packaging, then secreted in vesicles that fuse with the plasma membrane."}],"misconceptions":["The cell membrane is a rigid, static wall.","Lysosomes synthesise proteins.","All ribosomes are attached to the endoplasmic reticulum."],"revision_notes":"Fluid mosaic membrane. Nucleus: DNA. Ribosome: protein. RER: fold/transport protein; SER: lipids. Golgi: modify/sort. Mitochondrion: ATP. Lysosome: digestion. Chloroplast: photosynthesis."}$c$::jsonb),
('20000000-0000-4000-8000-000000001027','10000000-0000-4000-8000-000000000016','biomolecules','Biomolecules and enzymes','Carbohydrates, proteins, lipids, nucleic acids and enzyme action.',2,$c${"explanation":"Living cells build large molecules from smaller units. Carbohydrates are sugars and polymers such as starch and cellulose; monosaccharides join by glycosidic bonds. Proteins are polymers of amino acids linked by peptide bonds, and their folded shape determines their function. Lipids are hydrophobic molecules used in membranes and energy storage. Nucleic acids, DNA and RNA, are polymers of nucleotides that store and transmit genetic information. Enzymes are protein catalysts that lower activation energy and are specific to their substrates. Temperature and pH change their shape; beyond an optimum, denaturation destroys activity. Cofactors and inhibitors regulate enzyme action.","examples":[{"problem":"Why does an enzyme stop working at very high temperature?","solution":"Heat breaks the bonds maintaining its three-dimensional shape, denaturing the active site so the substrate no longer fits."},{"problem":"What bond joins two amino acids, and what is released?","solution":"A peptide bond forms between the carboxyl group of one and the amino group of the next, releasing water in a condensation reaction."}],"misconceptions":["Enzymes are used up in the reactions they catalyse.","All proteins are enzymes.","Enzymes work equally well at every pH."],"revision_notes":"Carbs: glycosidic; proteins: peptide; nucleic acids: phosphodiester. Enzymes lower activation energy, are specific and reusable. High heat/pH extremes denature."}$c$::jsonb),
('20000000-0000-4000-8000-000000001028','10000000-0000-4000-8000-000000000016','cell-cycle','Cell cycle, mitosis and meiosis','Interphase, the stages of mitosis, and how meiosis creates variation.',3,$c${"explanation":"The cell cycle consists of interphase and M phase. Interphase has G₁ growth, S-phase DNA replication and G₂ preparation. Mitosis then divides the nucleus: chromosomes condense in prophase, align at the equator in metaphase, separate in anaphase and decondense in telophase, followed by cytokinesis. Mitosis produces two genetically identical diploid cells for growth and repair. Meiosis has two divisions and halves the chromosome number, producing four haploid cells. Crossing over in prophase I and independent assortment in metaphase I create genetic variation, which is why meiosis is central to sexual reproduction.","examples":[{"problem":"A diploid cell has 46 chromosomes. How many chromosomes are in each product of meiosis?","solution":"Meiosis halves the number, so each of the four gametes has 23 chromosomes."},{"problem":"During which phase do sister chromatids separate in mitosis?","solution":"Anaphase, when spindle fibres pull the chromatids to opposite poles."}],"misconceptions":["DNA replication occurs during mitosis rather than interphase.","Meiosis produces identical diploid cells.","Crossing over happens in mitosis."],"revision_notes":"Interphase G₁-S-G₂; mitosis prophase-metaphase-anaphase-telophase. Mitosis: 2 identical diploid cells. Meiosis: 4 haploid cells; variation via crossing over and independent assortment."}$c$::jsonb),
('20000000-0000-4000-8000-000000001029','10000000-0000-4000-8000-000000000017','prose-analysis','Prose analysis','Theme, character, narrative voice and evidence in literary prose.',0,$c${"explanation":"Analysing prose means explaining how a writer shapes meaning, not merely retelling the plot. Identify the central theme and the conflict that develops it. Examine characterisation through what a character says, does, thinks and how others respond. Notice the narrative voice: first person creates intimacy and limited knowledge, while third-person omniscience can move between minds. Setting and symbol often carry emotional or social meaning. Support every claim with a short quotation and explain its effect. A strong response connects technique to theme, showing why the writer made that choice rather than only naming it.","examples":[{"problem":"How does first-person narration affect a story about a journey?","solution":"It limits the reader to the narrator's perceptions, creating suspense and making the narrator's biases part of the story's meaning."},{"problem":"Turn 'The author uses symbolism' into an analytical sentence.","solution":"'The broken clock symbolises the family's stalled grief, shown when the narrator refuses to repair it.'"}],"misconceptions":["Retelling the plot is analysis.","A character's speech always reflects the author's view.","Symbols have one fixed meaning regardless of context."],"revision_notes":"Theme + conflict. Character through speech, action, thought, others' reactions. Narrative voice shapes knowledge. Quote → technique → effect → theme."}$c$::jsonb),
('20000000-0000-4000-8000-000000001030','10000000-0000-4000-8000-000000000017','poetry-analysis','Poetry analysis','Imagery, figurative language, sound, structure and tone.',1,$c${"explanation":"Poetry compresses meaning through image, sound and form. Identify the speaker and the situation before interpreting. Examine imagery and figures of speech: simile, metaphor, personification, hyperbole and symbolism. Sound matters too: alliteration, assonance, rhyme and rhythm create emphasis and mood. Structure, including stanza breaks and line length, can control pace or isolate an idea. Tone is the speaker's attitude, which may be ironic or ambivalent. Build an interpretation from several details rather than decoding one device, and always explain how the technique produces the effect you claim.","examples":[{"problem":"What does a short final stanza of two lines usually achieve?","solution":"It can isolate a conclusion or reversal, giving the ending emphasis and making the reader pause."},{"problem":"Explain the effect of repeated 's' sounds in a line about a snake.","solution":"The sibilance mimics the snake's hiss and creates a tense, sinister mood, reinforcing the image."}],"misconceptions":["Rhyme is the most important feature of every poem.","The poet's biography is always the key to meaning.","Every metaphor must be interpreted symbolically."],"revision_notes":"Speaker/situation → imagery → sound → structure → tone → theme. Name device, quote, explain effect. Use several details, not one."}$c$::jsonb),
('20000000-0000-4000-8000-000000001031','10000000-0000-4000-8000-000000000017','note-making','Note-making and summarising','Extracting main ideas, organising notes and writing concise summaries.',2,$c${"explanation":"Note-making reduces a passage to its essential ideas in a form you can revise. Read the passage fully, identify the main idea of each paragraph, and distinguish it from examples and repetition. Use a title, numbered headings, sub-points and consistent abbreviations. Notes should use your own words and omit ornamental detail while keeping key terms and figures. A summary is continuous prose that states the central ideas in a fixed word limit, without copying long phrases or adding opinion. Both skills test whether you can identify importance, not whether you can copy quickly.","examples":[{"problem":"A paragraph lists five benefits of cycling and one drawback. What belongs in the notes?","solution":"Note the main idea (cycling has several benefits) and list the benefits compactly, plus the drawback as a counterpoint; omit repeated explanations."},{"problem":"How should you trim a 120-word summary to 80 words without losing meaning?","solution":"Remove examples, repeated adjectives and redundant transitions, then combine related sentences; retain the main claim and essential qualifications."}],"misconceptions":["Good notes copy the passage word for word.","A summary should include the writer's examples in full.","Headings and abbreviations make notes less accurate."],"revision_notes":"Main idea per paragraph; own words; headings, sub-points, abbreviations. Summary: central ideas only, within the word limit, no opinion."}$c$::jsonb),
('20000000-0000-4000-8000-000000001032','10000000-0000-4000-8000-000000000017','advanced-writing','Articles, speeches and formal letters','Planning and drafting advanced writing for a specified audience and purpose.',3,$c${"explanation":"Advanced writing tasks specify a format, audience and purpose, and each choice should serve them. An article needs a title, an engaging opening, organised paragraphs and a conclusion that returns to the central idea. A speech uses direct address, rhetorical questions and repetition to hold listeners, and it must sound natural when spoken. A formal letter follows the correct layout and maintains a polite, purposeful tone. Before writing, spend a minute planning the main points and their order. Use topic sentences, evidence or examples, and linking words to create coherence. Finish by checking register, grammar and the word limit.","examples":[{"problem":"Plan a speech persuading students to reduce plastic waste.","solution":"Hook with a local statistic, state the problem, give two practical actions, answer the likely objection about convenience, and end with a direct challenge to the audience."},{"problem":"What tone should a letter to a newspaper editor use?","solution":"Formal, respectful and concise, even when arguing strongly; avoid slang, personal attacks and emotional exaggeration."}],"misconceptions":["A speech should be written exactly like an essay.","Formal writing means using long words regardless of clarity.","The audience and purpose affect only the greeting."],"revision_notes":"Plan points first. Article: title, hook, paragraphs, conclusion. Speech: direct address, rhetoric, spoken rhythm. Formal letter: layout + polite tone. Check register and limit."}$c$::jsonb),
('20000000-0000-4000-8000-000000001033','10000000-0000-4000-8000-000000000018','solution-concentration','Solutions and concentration','Solubility, Raoult''s law, ideal solutions and concentration units.',0,$c${"explanation":"A solution is a homogeneous mixture of solute and solvent. Solubility depends on the nature of the substances, temperature and, for gases, pressure; Henry's law states that the solubility of a gas is proportional to its partial pressure. Raoult's law says the partial vapour pressure of each volatile component is its mole fraction times the vapour pressure of the pure component. Ideal solutions obey Raoult's law at all compositions and have zero enthalpy of mixing, while real solutions deviate positively or negatively and may form azeotropes. Concentration can be expressed as molarity, molality, mole fraction or mass percentage.","examples":[{"problem":"The vapour pressure of pure A is 100 mmHg and of pure B is 40 mmHg. Find the total pressure for a mixture with mole fractions 0.3 A and 0.7 B, assuming ideal behaviour.","solution":"p = 0.3 × 100 + 0.7 × 40 = 30 + 28 = 58 mmHg."},{"problem":"Why does the solubility of most gases decrease as temperature rises?","solution":"Dissolution of a gas is exothermic, so heating shifts the equilibrium toward the gaseous state, reducing solubility."}],"misconceptions":["All solutions obey Raoult's law.","Henry's law relates solubility to temperature rather than pressure.","Mole fraction depends on the volume of the solution."],"revision_notes":"Henry: gas solubility ∝ partial pressure. Raoult: pᵢ = xᵢpᵢ°. Ideal: obeys Raoult, ΔHmix = 0. Units: M, m, x, mass %."}$c$::jsonb),
('20000000-0000-4000-8000-000000001034','10000000-0000-4000-8000-000000000018','colligative-properties','Colligative properties','Vapour-pressure lowering, boiling and freezing points, osmosis and van''t Hoff factor.',1,$c${"explanation":"Colligative properties depend on the number of solute particles, not their identity, for dilute non-volatile solutions. Adding solute lowers the vapour pressure, which raises the boiling point and lowers the freezing point. Osmosis is the movement of solvent through a semipermeable membrane from lower to higher solute concentration; osmotic pressure π = iCRT opposes it. The van't Hoff factor i accounts for dissociation or association: i is greater than 1 for electrolytes that split into ions and less than 1 for associating solutes. These properties allow molar masses to be determined, though measurements can be distorted by association or dissociation.","examples":[{"problem":"Why does 0.1 M NaCl have a larger boiling-point elevation than 0.1 M glucose?","solution":"NaCl dissociates into two ions, so i ≈ 2 and it supplies about twice as many particles as glucose (i = 1)."},{"problem":"Calculate the osmotic pressure of 0.1 M glucose at 300 K (R = 0.0821 L atm mol⁻¹ K⁻¹).","solution":"π = iCRT = 1 × 0.1 × 0.0821 × 300 ≈ 2.46 atm."}],"misconceptions":["Colligative properties depend on the molar mass of the solute.","The van't Hoff factor is always 1.","Osmosis moves solute rather than solvent."],"revision_notes":"Colligative = particle number. ΔTb = iKbm; ΔTf = iKfm; π = iCRT. i > 1 dissociates, i < 1 associates."}$c$::jsonb),
('20000000-0000-4000-8000-000000001035','10000000-0000-4000-8000-000000000018','electrochemical-cells','Galvanic cells and electrode potentials','Cell EMF, standard electrode potentials, the Nernst equation and Gibbs energy.',2,$c${"explanation":"A galvanic cell converts chemical energy into electrical energy. Oxidation occurs at the anode and reduction at the cathode; electrons flow through the external circuit while ions migrate through the salt bridge. The standard cell potential is E°cell = E°cathode - E°anode, measured against the standard hydrogen electrode, which is assigned 0 V. A positive E°cell means the reaction is spontaneous under standard conditions and corresponds to a negative Gibbs energy change, ΔG° = -nFE°cell. The Nernst equation adjusts the potential for non-standard concentrations: E = E° - (RT/nF)lnQ. At equilibrium, E = 0 and Q = K.","examples":[{"problem":"E°(Cu²⁺/Cu) = +0.34 V and E°(Zn²⁺/Zn) = -0.76 V. Find E°cell for Zn-Cu.","solution":"Copper is the cathode: E°cell = 0.34 - (-0.76) = 1.10 V, positive, so the cell reaction is spontaneous."},{"problem":"What does Ecell = 0 imply about the cell reaction?","solution":"The cell has reached equilibrium; the forward and reverse reactions balance, so no net electrical work is done."}],"misconceptions":["Oxidation occurs at the cathode.","A negative E°cell means the reaction is spontaneous.","Electrons travel through the salt bridge."],"revision_notes":"Anode oxidation, cathode reduction. E°cell = E°cathode - E°anode. Spontaneous: E° > 0, ΔG° < 0. Nernst: E = E° - (0.059/n)logQ at 298 K."}$c$::jsonb),
('20000000-0000-4000-8000-000000001036','10000000-0000-4000-8000-000000000018','electrolysis','Electrolysis and conductance','Faraday''s laws, conductivity, electrolytic products and commercial cells.',3,$c${"explanation":"Electrolysis uses an external voltage to drive a non-spontaneous reaction. The mass deposited or liberated at an electrode is proportional to the charge passed: m = (Q/F)(M/z), where F = 96,485 C/mol and z is the number of electrons per ion. Conductance depends on ion concentration and mobility; strong electrolytes conduct well, while weak electrolytes increase sharply on dilution. Kohlrausch's law allows the limiting molar conductivity of a weak electrolyte to be found from strong electrolytes. Electrolysis produces substances such as chlorine, hydrogen and aluminium, and underpins electroplating and refining. Batteries and fuel cells convert stored chemical energy back into electricity.","examples":[{"problem":"How much copper is deposited by 0.5 mol of electrons at the cathode? (M(Cu) = 63.5 g/mol, Cu²⁺ + 2e⁻ → Cu)","solution":"0.5 mol e⁻ deposits 0.25 mol Cu, so mass = 0.25 × 63.5 ≈ 15.9 g."},{"problem":"Why does the molar conductivity of a weak acid rise steeply on dilution?","solution":"Dilution increases the degree of ionisation, so more ions are available to carry current, even though concentration falls."}],"misconceptions":["Electrolysis happens spontaneously without a power supply.","One mole of electrons deposits one mole of any metal.","Conductivity and molar conductivity are the same quantity."],"revision_notes":"Faraday: Q = nF; m = QM/(zF). Electrolysis is forced, not spontaneous. Molar conductivity rises on dilution, steeply for weak electrolytes."}$c$::jsonb),
('20000000-0000-4000-8000-000000001037','10000000-0000-4000-8000-000000000019','matrices','Matrices and matrix operations','Order, types, addition, scalar multiplication and transpose.',0,$c${"explanation":"A matrix is a rectangular array of numbers arranged in rows and columns; its order is rows × columns. Two matrices are equal only when they have the same order and corresponding entries are equal. Addition and subtraction require the same order and act entry by entry. Scalar multiplication multiplies every entry. The transpose Aᵀ swaps rows and columns, so an m × n matrix becomes n × m. A square matrix is symmetric if Aᵀ = A and skew-symmetric if Aᵀ = -A, which forces the diagonal entries of a skew-symmetric matrix to be zero. These operations obey familiar algebraic laws except that matrix multiplication is not generally commutative.","examples":[{"problem":"A is 2 × 3 and B is 3 × 2. Can A + B be formed? Can AB?","solution":"A + B cannot, because the orders differ. AB can be formed and is 2 × 2, since the inner dimensions 3 and 3 match."},{"problem":"If A is skew-symmetric, what is A + Aᵀ?","solution":"Aᵀ = -A, so A + Aᵀ = A - A = 0, the zero matrix."}],"misconceptions":["Matrices of different orders can always be added.","The transpose of a 2 × 3 matrix is 3 × 2 but has different entries.","AB always equals BA."],"revision_notes":"Order rows × columns. Add/subtract same order; scalar multiplies every entry. Transpose swaps rows/columns. Symmetric Aᵀ = A; skew Aᵀ = -A."}$c$::jsonb),
('20000000-0000-4000-8000-000000001038','10000000-0000-4000-8000-000000000019','matrix-algebra','Matrix multiplication and inverses','The row-column product, non-commutativity and elementary row operations.',1,$c${"explanation":"The product AB is defined when the number of columns of A equals the number of rows of B. Each entry of AB is the dot product of a row of A with a column of B. Matrix multiplication is associative and distributive but not commutative: AB and BA may differ or one may not exist. The identity matrix I has ones on the diagonal and zeros elsewhere, and IA = AI = A. A square matrix A is invertible if there is a matrix A⁻¹ with AA⁻¹ = A⁻¹A = I. Elementary row operations can reduce [A | I] to [I | A⁻¹], which is a practical way to compute an inverse.","examples":[{"problem":"A = [[1, 2], [3, 4]] and B = [[2, 0], [1, 5]]. Find AB.","solution":"AB = [[1×2 + 2×1, 1×0 + 2×5], [3×2 + 4×1, 3×0 + 4×5]] = [[4, 10], [10, 20]]."},{"problem":"Why is matrix multiplication not commutative?","solution":"Row-column pairing depends on order: AB uses rows of A with columns of B, while BA reverses those roles, so the products generally differ."}],"misconceptions":["Matrix multiplication multiplies corresponding entries.","AB always exists whenever A and B are square.","Every square matrix has an inverse."],"revision_notes":"AB: rows of A · columns of B; inner dimensions must match. Not commutative. AI = IA = A. Inverse: AA⁻¹ = I; find by row-reducing [A | I]."}$c$::jsonb),
('20000000-0000-4000-8000-000000001039','10000000-0000-4000-8000-000000000019','determinants','Determinants and the adjoint','Evaluating determinants, their properties and finding an inverse with the adjoint.',2,$c${"explanation":"A determinant is a number associated with a square matrix. For a 2 × 2 matrix [[a, b], [c, d]], det = ad - bc. For 3 × 3 matrices, expand along a row or column using cofactors. Swapping two rows changes the sign, multiplying a row by k multiplies the determinant by k, and adding a multiple of one row to another leaves it unchanged. If two rows are equal or a row is all zeros, the determinant is zero and the matrix is singular. The adjoint is the transpose of the cofactor matrix, and A⁻¹ = adj(A)/det(A) when det(A) ≠ 0.","examples":[{"problem":"Find the determinant of [[2, 3], [1, 4]].","solution":"det = 2×4 - 3×1 = 8 - 3 = 5."},{"problem":"A 3 × 3 matrix has det(A) = 0. What does this mean for A⁻¹?","solution":"A is singular, so A⁻¹ does not exist; the system it represents may have no unique solution."}],"misconceptions":["A determinant can be found for any rectangular matrix.","Swapping rows leaves the determinant unchanged.","If det(A) = 0, the inverse is the zero matrix."],"revision_notes":"2 × 2: ad - bc. Expand 3 × 3 by cofactors. det = 0 ⇒ singular. A⁻¹ = adj(A)/det(A), det ≠ 0."}$c$::jsonb),
('20000000-0000-4000-8000-000000001040','10000000-0000-4000-8000-000000000019','linear-equations','Solving systems with matrices','Matrix form AX = B, the inverse method, Cramer''s rule and consistency.',3,$c${"explanation":"A system of linear equations can be written as AX = B, where A holds the coefficients, X the unknowns and B the constants. If A is invertible, the unique solution is X = A⁻¹B. Cramer's rule expresses each unknown as a ratio of determinants, with the relevant column of A replaced by B. If det(A) = 0, the system may have infinitely many solutions or none; row reduction reveals which. Geometrically, two equations in two unknowns represent lines that intersect once, are parallel, or coincide. Matrices turn these cases into algebraic tests and extend the same reasoning to three or more unknowns.","examples":[{"problem":"Solve x + y = 3 and 2x - y = 0 using matrices.","solution":"A = [[1, 1], [2, -1]], det = -3, A⁻¹ = (-1/3)[[-1, -1], [-2, 1]]. X = A⁻¹[[3], [0]] = [[1], [2]], so x = 1, y = 2."},{"problem":"What does det(A) = 0 mean for the lines represented by AX = B?","solution":"The coefficient lines are parallel or coincident, so the system has no unique solution: either none or infinitely many."}],"misconceptions":["Cramer's rule works even when the determinant is zero.","A singular system always has no solution.","The inverse method applies to non-square coefficient matrices."],"revision_notes":"AX = B ⇒ X = A⁻¹B if det A ≠ 0. Cramer: xᵢ = det(Aᵢ)/det(A). det A = 0 ⇒ no unique solution (none or infinite)."}$c$::jsonb),
('20000000-0000-4000-8000-000000001041','10000000-0000-4000-8000-000000000020','meiosis','Meiosis and genetic variation','The two meiotic divisions, crossing over and independent assortment.',0,$c${"explanation":"Meiosis reduces the chromosome number from diploid to haploid and produces gametes. In meiosis I, homologous chromosomes pair in prophase I and crossing over exchanges segments between non-sister chromatids. In metaphase I, homologous pairs align independently, so the maternal and paternal chromosomes are distributed randomly. Anaphase I separates homologous chromosomes; meiosis II separates sister chromatids. The result is four haploid cells that differ genetically from one another and from the parent. Fertilisation then restores the diploid number. Meiosis is therefore central to sexual reproduction and to generating the variation on which natural selection acts.","examples":[{"problem":"A human cell has 46 chromosomes. How many chromosomes does each product of meiosis have, and why?","solution":"23, because meiosis I separates homologous pairs and meiosis II separates chromatids, halving the diploid number once."},{"problem":"How does crossing over increase variation?","solution":"It creates new combinations of alleles on a chromosome, so gametes carry gene combinations not present in either parent."}],"misconceptions":["Meiosis produces two identical cells.","Crossing over occurs between sister chromatids.","Chromosome number is halved during meiosis II."],"revision_notes":"Meiosis I: homologous chromosomes separate; crossing over in prophase I, independent assortment in metaphase I. Meiosis II: chromatids separate. Four haploid, varied cells."}$c$::jsonb),
('20000000-0000-4000-8000-000000001042','10000000-0000-4000-8000-000000000020','plant-reproduction','Sexual reproduction in flowering plants','Flower structure, gametophytes, pollination, double fertilisation and seed formation.',1,$c${"explanation":"A flower contains male and female reproductive organs. The anther's microsporangia produce pollen grains, each containing a generative cell and a tube cell. The ovule contains the embryo sac, a female gametophyte typically with seven cells and eight nuclei, including the egg and two polar nuclei. Pollination transfers pollen to the stigma, where it germinates and a pollen tube grows to the ovule. Double fertilisation follows: one male gamete fuses with the egg to form the zygote, and the other fuses with the two polar nuclei to form the triploid endosperm. The ovule becomes the seed and the ovary the fruit.","examples":[{"problem":"Why is fertilisation in flowering plants called double fertilisation?","solution":"Two fusions occur: syngamy forms the diploid zygote, and triple fusion forms the triploid primary endosperm nucleus."},{"problem":"What happens to the ovule and ovary after fertilisation?","solution":"The ovule develops into the seed, and the ovary develops into the fruit enclosing the seeds."}],"misconceptions":["Pollination and fertilisation are the same event.","The endosperm is diploid.","The fruit develops from the ovule."],"revision_notes":"Anther → pollen; ovule → embryo sac. Pollination then pollen tube. Double fertilisation: syngamy (2n zygote) + triple fusion (3n endosperm). Ovule → seed; ovary → fruit."}$c$::jsonb),
('20000000-0000-4000-8000-000000001043','10000000-0000-4000-8000-000000000020','human-reproduction','Human reproduction','Gametogenesis, the menstrual cycle, fertilisation, implantation and pregnancy.',2,$c${"explanation":"In humans, sperm form in the seminiferous tubules of the testes and mature in the epididymis; oogenesis begins before birth and completes only at fertilisation. The menstrual cycle has a follicular phase, ovulation around day 14 and a luteal phase in which the corpus luteum secretes progesterone. If fertilisation occurs in the fallopian tube, the zygote divides and travels to the uterus, where it implants in the endometrium. The placenta then exchanges nutrients, gases and wastes between mother and embryo and secretes hormones such as hCG and progesterone. Pregnancy ends with labour and parturition.","examples":[{"problem":"What is the role of the corpus luteum if fertilisation does not occur?","solution":"It degenerates, progesterone falls, and the endometrium is shed as menstruation."},{"problem":"Why is the placenta essential for the embryo?","solution":"It provides a large exchange surface for nutrients and oxygen and removes wastes, while also producing hormones that maintain pregnancy."}],"misconceptions":["Fertilisation normally occurs in the uterus.","The placenta allows free mixing of maternal and fetal blood.","Oogenesis is completed before birth."],"revision_notes":"Spermatogenesis in testes; oogenesis completes at fertilisation. Cycle: follicular → ovulation (~day 14) → luteal. Fertilisation in fallopian tube; implantation in uterus; placenta exchanges and secretes hCG/progesterone."}$c$::jsonb),
('20000000-0000-4000-8000-000000001044','10000000-0000-4000-8000-000000000020','reproductive-health','Reproductive health','Contraception, sexually transmitted infections, infertility and assisted reproduction.',3,$c${"explanation":"Reproductive health means physical, mental and social well-being in matters of reproduction. Contraception prevents pregnancy by different mechanisms: barrier methods block gametes, hormonal methods suppress ovulation, intrauterine devices affect implantation, and surgical methods block gamete transport. No method is perfectly effective, and condoms also reduce the transmission of sexually transmitted infections such as HIV, gonorrhoea and syphilis. Infertility can result from many causes and may be addressed with assisted reproductive technologies including IVF, in which fertilisation occurs outside the body before embryo transfer. Prenatal care, safe delivery and education all improve outcomes.","examples":[{"problem":"Why do condoms offer protection that hormonal pills do not?","solution":"Condoms form a physical barrier that reduces pathogen transmission, whereas hormonal pills prevent ovulation but do not block infections."},{"problem":"What is IVF?","solution":"In vitro fertilisation: eggs are collected and fertilised with sperm in the laboratory, and an embryo is transferred to the uterus."}],"misconceptions":["Hormonal contraceptives protect against STIs.","Infertility is always caused by the female partner.","IVF guarantees a pregnancy."],"revision_notes":"Contraception: barrier, hormonal, IUD, surgical. Condoms also reduce STI risk. Infertility → ART including IVF. Reproductive health includes care, education and safety."}$c$::jsonb),
('20000000-0000-4000-8000-000000001045','10000000-0000-4000-8000-000000000021','prose-comprehension','Prose comprehension and interpretation','Close reading, inference, characterisation, tone and supported interpretation.',0,$c${"explanation":"At Class 12, comprehension requires interpretation rather than recall. Read the passage twice: first for the overall movement of ideas, then for details that support an interpretation. Distinguish the author's attitude from a character's view, and notice shifts in tone. Characterisation is built through dialogue, action, description and the reactions of others. An interpretation should be arguable and supported: state the point, quote briefly, and explain how the language creates the effect. Avoid plot summary unless it is needed to explain a technique or theme. Exam answers are stronger when they use precise literary vocabulary.","examples":[{"problem":"A narrator describes a childhood home as 'smaller than I remembered'. What does this suggest?","solution":"The contrast between memory and present perception suggests the passage of time and the narrator's changed perspective, not merely a physical measurement."},{"problem":"How do you avoid plot summary in an interpretation?","solution":"Make a claim about technique or theme first, then use only the events that support it as evidence."}],"misconceptions":["A good answer retells the story in detail.","The author's views and the narrator's views are always identical.","A quotation supports any point without explanation."],"revision_notes":"Read twice. Claim → quote → effect → theme. Separate author, narrator and character. Use precise literary terms, avoid plot summary."}$c$::jsonb),
('20000000-0000-4000-8000-000000001046','10000000-0000-4000-8000-000000000021','poetry-analysis','Poetry: language, form and meaning','Diction, imagery, symbolism, rhythm and ambiguity in poetry.',1,$c${"explanation":"Poetry analysis begins with the speaker and the situation, then moves to how language creates meaning. Diction is the writer's choice of words, and its connotations often carry more weight than literal meaning. Imagery appeals to the senses; symbolism gives an object or action a larger significance. Form matters: line breaks control pace, enjambment runs meaning across lines, and rhyme can create pattern or irony. Tone may be complex or ambivalent, and a poem can hold conflicting ideas. Strong answers tolerate ambiguity and build an interpretation from several details rather than reducing the poem to a single message.","examples":[{"problem":"What is the effect of enjambment in a poem about a journey?","solution":"It carries the sentence across the line break, imitating continuous movement and preventing the reader from settling at each line."},{"problem":"How should you discuss an ambiguous symbol?","solution":"Acknowledge both possible meanings and show how each is supported: 'The locked door suggests both protection and exclusion, reinforced by...'"}],"misconceptions":["Every poem has one correct paraphrase.","Rhyme is always used for pleasant sound rather than meaning.","Ambiguity means the poem has no meaning."],"revision_notes":"Speaker/situation → diction → imagery → symbolism → form → tone. Line breaks and enjambment shape pace. Build interpretation from multiple details; allow complexity."}$c$::jsonb),
('20000000-0000-4000-8000-000000001047','10000000-0000-4000-8000-000000000021','unseen-passages','Unseen passages and note-making','Handling unfamiliar texts, extracting main ideas and writing concise notes.',2,$c${"explanation":"Unseen passages test transferable reading skills, not prior knowledge. Skim to identify the topic and purpose, then scan for the information each question requires. Distinguish main ideas from supporting examples and recognise the writer's attitude through word choice. For note-making, give the passage a title, group related points under headings, use consistent abbreviations and keep the notes brief and in your own words. A summary should express the central ideas in continuous prose within the word limit, without examples, repetition or personal opinion. For vocabulary questions, use the surrounding sentence to infer meaning.","examples":[{"problem":"A passage discusses both benefits and risks of urban gardens. How should the notes be organised?","solution":"Use two headings, 'Benefits' and 'Risks', with compact sub-points under each, plus a title that captures the balanced discussion."},{"problem":"How do you infer the meaning of an unfamiliar word?","solution":"Use contrast or cause-effect clues in the sentence, substitute a likely synonym, and check that the whole sentence still makes sense."}],"misconceptions":["Unseen passages require outside subject knowledge.","A summary should include every example.","Notes should be full sentences copied from the passage."],"revision_notes":"Skim for topic/purpose, scan for question details. Notes: title, headings, sub-points, abbreviations. Summary: central ideas only, own words, word limit."}$c$::jsonb),
('20000000-0000-4000-8000-000000001048','10000000-0000-4000-8000-000000000021','writing-argument','Argumentative and formal writing','Articles, letters to the editor, reports and speeches that argue a clear position.',3,$c${"explanation":"Argumentative writing needs a clear position, logical structure and awareness of the audience. An article uses a title, an engaging opening, developed paragraphs and a conclusion that reinforces the argument. A letter to the editor is formal and concise, identifies the issue, presents evidence and proposes action. A report is organised under headings and presents findings objectively. A speech uses direct address, rhetorical questions and controlled repetition, and must sound natural when spoken. Anticipate the strongest counterargument and answer it rather than ignoring it. Use linking words to show contrast, cause and consequence, and edit for accuracy and register.","examples":[{"problem":"How do you answer a counterargument in a speech about school start times?","solution":"Acknowledge it fairly, then rebut it with evidence: 'Some worry about transport, but later starts can be matched by adjusted bus schedules.'"},{"problem":"What is the difference in tone between a report and a letter to the editor?","solution":"A report is objective and organised under headings; a letter to the editor is formal but persuasive, arguing a position for a public audience."}],"misconceptions":["A strong argument ignores opposing views.","Formal writing should avoid all short sentences.","A speech and an article use exactly the same structure."],"revision_notes":"Position + reasons + evidence + counterargument/rebuttal + conclusion. Article: title/hook; letter: formal and concise; report: headings, objective; speech: direct address, rhetoric."}$c$::jsonb)
